public class Main {
    // The method receives a COPY of the reference; both copies point to one array.
    static void mutate(int[] a) {
        a[0] = 99;                 // writes into the shared array: the caller sees it
    }

    static void reassign(int[] a) {
        a = new int[]{7, 7, 7};    // only the local copy now points somewhere else
    }

    static String show(int[] a) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) sb.append(i > 0 ? " " : "").append(a[i]);
        return sb.toString();
    }

    public static void main(String[] args) {
        int[] arr = {1, 2, 3};
        System.out.println("start:          " + show(arr));
        mutate(arr);
        System.out.println("after mutate:   " + show(arr));
        reassign(arr);             // has no effect on arr
        System.out.println("after reassign: " + show(arr));
    }
    // Time O(1), extra space O(1).
}

