#include <bits/stdc++.h>
using namespace std;

// A pointer passed by value behaves like a Java reference: the address is copied.
void mutate(int* a) {
    a[0] = 99;                 // writes into the shared array: the caller sees it
}

void reassign(int* a) {
    static int other[3] = {7, 7, 7};
    a = other;                 // only the local copy of the address changes
}

void show(const string& label, int* a, int n) {
    cout << label;
    for (int i = 0; i < n; i++) cout << (i > 0 ? " " : "") << a[i];
    cout << "\n";
}

int main() {
    int arr[3] = {1, 2, 3};
    show("start:          ", arr, 3);
    mutate(arr);
    show("after mutate:   ", arr, 3);
    reassign(arr);             // has no effect on arr
    show("after reassign: ", arr, 3);
    return 0;
}
// Time O(1), extra space O(1).

