public class Main {
    // Each call adds one frame to the stack; the frame is removed on return.
    static int countFrames(int n) {
        if (n == 0) return 0;
        return 1 + countFrames(n - 1);
    }

    // The array is created on the heap, so it survives after this method returns.
    static int[] makeArray() {
        int[] local = {10, 20, 30};   // 'local' (a reference) is in the stack frame
        return local;                 // the frame goes away, the array does not
    }

    public static void main(String[] args) {
        int depth = 500;
        System.out.println("recursion of depth " + depth + " used " + countFrames(depth) + " stack frames");
        int[] arr = makeArray();
        int sum = 0;
        for (int x : arr) sum += x;
        System.out.println("array made inside makeArray is still usable: " + arr[0] + " " + arr[1] + " " + arr[2]);
        System.out.println("sum = " + sum);
    }
    // Time O(depth), stack space O(depth), heap space O(1).
}

