using namespace std;

// Each call adds one frame to the stack; the frame is removed on return.
int countFrames(int n) {
    if (n == 0) return 0;
    return 1 + countFrames(n - 1);
}

// 'new' puts the array on the heap, so it survives after this function returns.
int* makeArray() {
    int* local = new int[3]{10, 20, 30};   // the pointer 'local' is in the frame
    return local;                          // the frame goes away, the array does not
}

int main() {
    int depth = 500;
    cout << "recursion of depth " << depth << " used " << countFrames(depth) << " stack frames\n";
    int* arr = makeArray();
    int sum = 0;
    for (int i = 0; i < 3; i++) sum += arr[i];
    cout << "array made inside makeArray is still usable: " << arr[0] << " " << arr[1] << " " << arr[2] << "\n";
    cout << "sum = " << sum << "\n";
    delete[] arr;                          // C++ has no garbage collector: free it yourself
    return 0;
}
// Time O(depth), stack space O(depth), heap space O(1).

