import java.io.BufferedReader;
import java.io.IOException;
import java.io.StringReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        // In a real judge this would be new InputStreamReader(System.in).
        String input = "5\n3 1 4 1 5\n";
        BufferedReader br = new BufferedReader(new StringReader(input));
        int n = Integer.parseInt(br.readLine().trim());
        // StringTokenizer splits on spaces without the regular expressions Scanner uses.
        StringTokenizer st = new StringTokenizer(br.readLine());
        StringBuilder out = new StringBuilder();   // collect all output here
        out.append("n = ").append(n).append('\n');
        long sum = 0;
        for (int i = 0; i < n; i++) {
            int x = Integer.parseInt(st.nextToken());
            sum += x;
            out.append("read ").append(x).append(", running sum ").append(sum).append('\n');
        }
        System.out.print(out);                     // one write instead of n writes
    }
    // Time O(n), space O(n) for the buffered output.
}

