    long long sum = 0;
    for (int i = 0; i < n; i++) {
        int x;
        in >> x;
        sum += x;
        out << "read " << x << ", running sum " << sum << '\n';
    }
    cout << out.str();                 // one write instead of n writes
    return 0;
}
// Time O(n), space O(n) for the buffered output.

