using System;
using System.IO;
using System.Text;

class Program {
    static void Main() {
        // In a real judge this would be Console.In (ideally wrapped in a big buffer).
        TextReader reader = new StringReader("5\n3 1 4 1 5\n");
        // Read everything in one go and split into tokens.
        string[] tokens = reader.ReadToEnd().Split(new char[] {' ', '\n'}, StringSplitOptions.RemoveEmptyEntries);
        int pos = 0;
        int n = int.Parse(tokens[pos++]);
        StringBuilder sb = new StringBuilder();   // collect all output here
        sb.Append("n = ").Append(n).Append('\n');
        long sum = 0;
        for (int i = 0; i < n; i++) {
            int x = int.Parse(tokens[pos++]);
            sum += x;
            sb.Append("read ").Append(x).Append(", running sum ").Append(sum).Append('\n');
        }
        Console.Write(sb.ToString());             // one write instead of n writes
    }
    // Time O(n), space O(n) for the tokens and the buffered output.
}

