public class Main {
    public static void main(String[] args) {
        int a = 100000, b = 100000;
        System.out.println("a = " + a + ", b = " + b);

        int wrong = a * b;              // 10^10 does not fit in 32 bits: it wraps around
        long right = (long) a * b;      // cast FIRST, so the multiplication is 64-bit
        System.out.println("32-bit product: " + wrong);
        System.out.println("64-bit product: " + right);

        int max = Integer.MAX_VALUE;    // 2147483647
        int next = max + 1;             // wraps to the smallest int, no error is raised
        System.out.println(max + " + 1 in 32 bits: " + next);

        // Rule: work out the largest intermediate value, then pick the type.
        long pairs = 100000L * 99999 / 2;
        System.out.println("pairs among 100000 items: " + pairs);
    }
    // Time O(1), space O(1).
}

