#include <bits/stdc++.h>
using namespace std;

int main() {
    int a = 100000, b = 100000;
    cout << "a = " << a << ", b = " << b << "\n";

    // Signed overflow is undefined in C++, so we wrap through unsigned to show it safely.
    int wrong = (int)((unsigned)a * (unsigned)b);   // 10^10 does not fit in 32 bits
    long long right = (long long)a * b;             // cast FIRST: 64-bit multiplication
    cout << "32-bit product: " << wrong << "\n";
    cout << "64-bit product: " << right << "\n";

    int mx = INT_MAX;                               // 2147483647
    int nxt = (int)((unsigned)mx + 1u);             // wraps to the smallest int
    cout << mx << " + 1 in 32 bits: " << nxt << "\n";

    // Rule: work out the largest intermediate value, then pick the type.
    long long pairs = 100000LL * 99999 / 2;
    cout << "pairs among 100000 items: " << pairs << "\n";
    return 0;
}
// Time O(1), space O(1).

