code.java:
public class Main {
    static String yesNo(boolean b) {
        return b ? "yes" : "no";
    }

    public static void main(String[] args) {
        // Autoboxing calls Integer.valueOf, which reuses objects for -128..127.
        Integer a = 127, b = 127;
        Integer c = 1000, d = 1000;      // outside the cache: two separate objects

        // == on Integer compares references (is it the same object?), not values.
        System.out.println("127 and 127 are the same object: " + yesNo(a == b));
        System.out.println("1000 and 1000 are the same object: " + yesNo(c == d));

        // equals compares the numbers inside: this is what you almost always want.
        System.out.println("1000 equals 1000 by value: " + yesNo(c.equals(d)));

        // Unboxing to int also compares values.
        int x = c, y = d;
        System.out.println("1000 == 1000 after unboxing to int: " + yesNo(x == y));
    }
    // Time O(1), space O(1).
}

