# A tiny copy of Java's Integer: a box object that holds one number.
class Box:
    def __init__(self, value):
        self.value = value


# Like Java, keep one shared box for each value from -128 to 127.
CACHE = {v: Box(v) for v in range(-128, 128)}


def value_of(v):
    return CACHE[v] if -128 <= v <= 127 else Box(v)


def yes_no(b):
    return "yes" if b else "no"


a, b = value_of(127), value_of(127)
c, d = value_of(1000), value_of(1000)   # outside the cache: two separate objects

# "is" asks: is it the same object? (Java's == on Integer does the same.)
print("127 and 127 are the same object: " + yes_no(a is b))
print("1000 and 1000 are the same object: " + yes_no(c is d))
# Comparing the numbers inside is what you almost always want.
print("1000 equals 1000 by value: " + yes_no(c.value == d.value))
x, y = c.value, d.value
print("1000 == 1000 after unboxing to int: " + yes_no(x == y))
# Time O(1), space O(1) apart from the 256 cached boxes.

