#include <bits/stdc++.h>
using namespace std;

// A tiny copy of Java's Integer: a box object that holds one number.
struct Box { int value; };

// Like Java, keep one shared box for each value from -128 to 127.
map<int, Box*> cache_;

Box* valueOf(int v) {
    if (v >= -128 && v <= 127) return cache_[v];
    return new Box{v};
}

string yesNo(bool b) { return b ? "yes" : "no"; }

int main() {
    for (int v = -128; v <= 127; v++) cache_[v] = new Box{v};
    Box *a = valueOf(127), *b = valueOf(127);
    Box *c = valueOf(1000), *d = valueOf(1000);   // outside the cache: two objects

    // == on pointers asks: is it the same object? (Java's == on Integer does the same.)
    cout << "127 and 127 are the same object: " << yesNo(a == b) << "\n";
    cout << "1000 and 1000 are the same object: " << yesNo(c == d) << "\n";
    // Comparing the numbers inside is what you almost always want.
    cout << "1000 equals 1000 by value: " << yesNo(c->value == d->value) << "\n";
    int x = c->value, y = d->value;
    cout << "1000 == 1000 after unboxing to int: " << yesNo(x == y) << "\n";
    return 0;
}
// Time O(1), space O(1) apart from the 256 cached boxes.

code.csharp:
using System;
using System.Collections.Generic;

// A tiny copy of Java's Integer: a box object that holds one number.
class Box {
    public int Value;
    public Box(int v) { Value = v; }
}

class Program {
    // Like Java, keep one shared box for each value from -128 to 127.
    static Dictionary<int, Box> cache = new Dictionary<int, Box>();

    static Box ValueOf(int v) {
        return v >= -128 && v <= 127 ? cache[v] : new Box(v);
    }

    static string YesNo(bool b) { return b ? "yes" : "no"; }

    static void Main() {
        for (int v = -128; v <= 127; v++) cache[v] = new Box(v);
        Box a = ValueOf(127), b = ValueOf(127);
        Box c = ValueOf(1000), d = ValueOf(1000);   // outside the cache: two objects

        // ReferenceEquals asks: is it the same object? (Java's == on Integer does the same.)
        Console.WriteLine("127 and 127 are the same object: " + YesNo(ReferenceEquals(a, b)));
        Console.WriteLine("1000 and 1000 are the same object: " + YesNo(ReferenceEquals(c, d)));
        // Comparing the numbers inside is what you almost always want.
        Console.WriteLine("1000 equals 1000 by value: " + YesNo(c.Value == d.Value));
        int x = c.Value, y = d.Value;
        Console.WriteLine("1000 == 1000 after unboxing to int: " + YesNo(x == y));
    }
    // Time O(1), space O(1) apart from the 256 cached boxes.
}

code.java:
public class Main {
    public static void main(String[] args) {
        int n = 1000;
        System.out.println("appends: " + n);

        // Slow way: every += makes a new String and copies all old characters.
        String s = "";
        long copied = 0;
        for (int i = 0; i < n; i++) {
            s += "x";
            copied += s.length();       // characters written to build this new String
        }
        System.out.println("characters copied with s += x: " + copied);

        // Fast way: StringBuilder keeps a growing array and adds at the end.
        StringBuilder sb = new StringBuilder();
        long written = 0;
        for (int i = 0; i < n; i++) {
            sb.append('x');
            written++;                  // one character per append (amortised)
        }
        System.out.println("characters written with a builder: " + written);
        System.out.println("both strings are equal: " + (s.equals(sb.toString()) ? "yes" : "no"));
    }
    // += loop: O(n^2) time. Builder: O(n) time. Both O(n) space.
}

