#include <bits/stdc++.h>
using namespace std;

int main() {
    int n = 1000;
    cout << "appends: " << n << "\n";

    // Slow way: s = s + "x" builds a new string and copies all old characters.
    string s = "";
    long long copied = 0;
    for (int i = 0; i < n; i++) {
        s = s + "x";
        copied += (long long)s.size();   // characters written to build this new string
    }
    cout << "characters copied with s += x: " << copied << "\n";

    // Fast way: push_back adds at the end of a growing buffer (std::string is mutable).
    string sb;
    long long written = 0;
    for (int i = 0; i < n; i++) {
        sb.push_back('x');
        written++;                       // one character per append (amortised)
    }
    cout << "characters written with a builder: " << written << "\n";
    cout << "both strings are equal: " << (s == sb ? "yes" : "no") << "\n";
    return 0;
}
// s = s + x loop: O(n^2) time. push_back: O(n) time. Both O(n) space.

