public class Main {
    static final long BUDGET = 100_000_000L;   // about 10^8 simple steps per second

    // Prints how many steps a complexity needs and whether that fits the budget.
    static void report(String name, long steps) {
        String verdict = steps <= BUDGET ? "fits" : "too slow";
        System.out.println(name + " needs " + steps + " steps: " + verdict);
    }

    public static void main(String[] args) {
        int n = 100000;
        System.out.println("N = " + n + ", budget = " + BUDGET + " steps per second");

        // log2(N) rounded up: how many times you can halve N.
        int log = 0;
        while ((1 << log) < n) log++;

        report("O(N)", n);
        report("O(N log N)", (long) n * log);
        report("O(N^2)", (long) n * n);        // long: 10^10 does not fit in an int
    }
    // Time O(log N), space O(1).
}

