public class Main {
    // Brute force: for every start, add up the next k values. O(N*K).
    static int brute(int[] a, int k) {
        int best = Integer.MIN_VALUE;
        for (int i = 0; i + k <= a.length; i++) {
            int sum = 0;
            for (int j = i; j < i + k; j++) sum += a[j];
            best = Math.max(best, sum);
        }
        return best;
    }

    // Optimised: the next window is the old one plus one value, minus one value. O(N).
    static int sliding(int[] a, int k) {
        int sum = 0;
        for (int i = 0; i < k; i++) sum += a[i];
        int best = sum;
        for (int i = k; i < a.length; i++) {
            sum += a[i] - a[i - k];     // slide: add the new value, drop the oldest
            best = Math.max(best, sum);
        }
        return best;
    }

    public static void main(String[] args) {
        int[] a = {2, 1, 5, 1, 3, 2};
        int k = 3;
        System.out.println("array: 2 1 5 1 3 2, k = " + k);
        System.out.println("brute force, O(N*K): " + brute(a, k));
        System.out.println("sliding window, O(N): " + sliding(a, k));
    }
    // Both use O(1) extra space; the brute force is the test oracle for the fast one.
}

