public class Main {
    static int seed;

    // Tiny random generator with a fixed seed, so every run gives the same tests.
    static int next() {
        seed = (seed * 75 + 74) % 65537;
        return seed;
    }

    // Obviously correct: try every subarray. O(N^2).
    static int brute(int[] a) {
        int best = a[0];
        for (int i = 0; i < a.length; i++) {
            int sum = 0;
            for (int j = i; j < a.length; j++) { sum += a[j]; best = Math.max(best, sum); }
        }
        return best;
    }

    // Kadane, O(N). The buggy version starts best at 0, which is wrong for all-negative input.
    static int fast(int[] a, boolean buggy) {
        int best = buggy ? 0 : a[0], cur = 0;
        for (int x : a) { cur = Math.max(x, cur + x); best = Math.max(best, cur); }
        return best;
    }

    static void stress(String name, boolean buggy) {
        seed = 1;
        for (int t = 1; t <= 1000; t++) {
            int[] a = new int[1 + next() % 6];                         // small sizes: 1..6
            for (int i = 0; i < a.length; i++) a[i] = next() % 21 - 10; // small values: -10..10
            int b = brute(a), f = fast(a, buggy);
            if (b != f) {                                               // stop at the first mismatch
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < a.length; i++) sb.append(i > 0 ? " " : "").append(a[i]);
                System.out.println(name + ": mismatch on test " + t + ", input [" + sb + "], brute = " + b + ", fast = " + f);
                return;
            }
        }
        System.out.println(name + ": all 1000 tests passed");
    }

    public static void main(String[] args) {
        System.out.println("problem: largest sum of a non-empty subarray");
        stress("correct Kadane", false);
        stress("buggy Kadane", true);
    }
    // Time O(tests * N^2) for the brute force, space O(N).
}

