import java.util.Arrays;

public class Main {
    public static void main(String[] args) {
        String[] names = {"Asha", "Ben", "Cara", "Dev", "Eli"};
        int[] scores = {90, 75, 90, 75, 60};
        Integer[] order = {0, 1, 2, 3, 4};       // positions to sort, as objects

        StringBuilder in = new StringBuilder();
        for (int i = 0; i < names.length; i++) in.append(i > 0 ? " " : "").append(names[i]).append(":").append(scores[i]);
        System.out.println("input: " + in);

        // Object arrays are sorted with TimSort, which is stable.
        // Integer.compare is safe; "scores[y] - scores[x]" could overflow for huge values.
        Arrays.sort(order, (x, y) -> Integer.compare(scores[y], scores[x]));

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < order.length; i++) out.append(i > 0 ? " " : "").append(names[order[i]]).append(":").append(scores[order[i]]);
        // Asha stays before Cara, and Ben before Dev: equal scores keep input order.
        System.out.println("by score, high first: " + out);
    }
    // Time O(N log N), space O(N).
}

