public class Main {
    // child[v] is the only child of node v, or -1 for the last node (a path-shaped tree).
    static int[] buildChain(int n) {
        int[] child = new int[n];
        for (int v = 0; v < n; v++) child[v] = (v + 1 < n) ? v + 1 : -1;
        return child;
    }

    // Recursive depth: one stack frame per node. Fine for 500, crashes for 1,000,000.
    static int depthRecursive(int[] child, int v) {
        if (v == -1) return 0;
        return 1 + depthRecursive(child, child[v]);
    }

    // Same walk with our own stack kept on the heap, so depth is limited only by memory.
    static int depthIterative(int[] child) {
        int[] stack = new int[child.length];
        int[] depth = new int[child.length];
        int top = 0, best = 0;
        stack[top++] = 0;
        depth[0] = 1;
        while (top > 0) {
            int v = stack[--top];                 // pop
            best = Math.max(best, depth[v]);
            int c = child[v];
            if (c != -1) { depth[c] = depth[v] + 1; stack[top++] = c; }   // push the child
        }
        return best;
    }

    public static void main(String[] args) {
        int[] small = buildChain(500);
        System.out.println("recursive, chain of 500 nodes: depth " + depthRecursive(small, 0));
        System.out.println("explicit stack, chain of 500 nodes: depth " + depthIterative(small));
        int[] big = buildChain(1000000);
        System.out.println("explicit stack, chain of 1000000 nodes: depth " + depthIterative(big));
    }
    // Time O(N), space O(N) on the heap instead of the call stack.
}

