public class Main {
    static String show(int[][] g) {
        StringBuilder sb = new StringBuilder();
        for (int r = 0; r < g.length; r++) {
            if (r > 0) sb.append(" | ");
            for (int c = 0; c < g[r].length; c++) sb.append(c > 0 ? " " : "").append(g[r][c]);
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        int[][] grid = {{1, 2}, {3, 4}};
        System.out.println("grid at start: " + show(grid));

        // Shallow: a new outer array, but it holds the SAME row objects.
        int[][] shallow = grid.clone();
        shallow[0][0] = 99;                     // also changes grid[0][0]
        System.out.println("after shallow[0][0] = 99, grid is: " + show(grid));

        // Deep: clone every row too, so nothing is shared.
        int[][] deep = new int[grid.length][];
        for (int r = 0; r < grid.length; r++) deep[r] = grid[r].clone();
        deep[1][1] = -5;                        // grid is not affected
        System.out.println("after deep[1][1] = -5, grid is: " + show(grid));
        System.out.println("the deep copy is: " + show(deep));
    }
    // Shallow copy: O(rows) time and space. Deep copy: O(rows * cols).
}

