#include <bits/stdc++.h>
using namespace std;

// Rows held through pointers behave like a Java 2D array (an array of references).
typedef vector<shared_ptr<vector<int>>> Grid;

string show(const Grid& g) {
    string s;
    for (size_t r = 0; r < g.size(); r++) {
        if (r > 0) s += " | ";
        for (size_t c = 0; c < g[r]->size(); c++) s += (c > 0 ? " " : "") + to_string((*g[r])[c]);
    }
    return s;
}

int main() {
    Grid grid = {make_shared<vector<int>>(vector<int>{1, 2}), make_shared<vector<int>>(vector<int>{3, 4})};
    cout << "grid at start: " << show(grid) << "\n";

    // Shallow: the outer vector is copied, but the pointers lead to the SAME rows.
    Grid shallow = grid;
    (*shallow[0])[0] = 99;                  // also changes grid[0][0]
    cout << "after shallow[0][0] = 99, grid is: " << show(grid) << "\n";

    // Deep: make a new row for every row. (A plain vector<vector<int>> does this on copy.)
    Grid deep;
    for (auto& row : grid) deep.push_back(make_shared<vector<int>>(*row));
    (*deep[1])[1] = -5;                     // grid is not affected
    cout << "after deep[1][1] = -5, grid is: " << show(grid) << "\n";
    cout << "the deep copy is: " << show(deep) << "\n";
    return 0;
}
// Shallow copy: O(rows) time and space. Deep copy: O(rows * cols).

