public class Main {
    static String hex(int cp) {
        return "U+" + Integer.toHexString(cp).toUpperCase();
    }

    public static void main(String[] args) {
        // 'a', one emoji (code point U+1F600, stored as two chars), then 'b'.
        String s = "a😀b";
        System.out.println("text: a, emoji U+1F600, b");
        System.out.println("UTF-16 code units (length): " + s.length());

        int[] cps = s.codePoints().toArray();     // real characters, one int each
        System.out.println("code points: " + cps.length);

        // Correct reverse: walk the code points backwards.
        StringBuilder good = new StringBuilder();
        for (int i = cps.length - 1; i >= 0; i--) good.append(hex(cps[i])).append(i > 0 ? " " : "");
        System.out.println("reversed by code point: " + good);

        // Wrong reverse: walking chars backwards splits the surrogate pair.
        StringBuilder bad = new StringBuilder();
        for (int i = s.length() - 1; i >= 0; i--) bad.append(hex(s.charAt(i))).append(i > 0 ? " " : "");
        System.out.println("reversed by code unit (broken): " + bad);
    }
    // Time O(N), space O(N).
}

