#include <bits/stdc++.h>
using namespace std;

void show(const string& label, const vector<unsigned>& v) {
    printf("%s", label.c_str());
    for (size_t i = v.size(); i-- > 0;) printf("U+%X%s", v[i], i > 0 ? " " : "");   // prints backwards
    printf("\n");
}

int main() {
    // 'a', one emoji (code point U+1F600, stored as two 16-bit units), then 'b'.
    u16string s = u"a\U0001F600b";
    printf("text: a, emoji U+1F600, b\n");
    printf("UTF-16 code units (length): %d\n", (int)s.size());

    // Join each high+low surrogate pair into one code point.
    vector<unsigned> cps, units;
    for (size_t i = 0; i < s.size(); i++) {
        unsigned u = s[i];
        units.push_back(u);
        if (u >= 0xD800 && u <= 0xDBFF && i + 1 < s.size()) {
            unsigned lo = s[i + 1];
            units.push_back(lo);
            cps.push_back(0x10000 + ((u - 0xD800) << 10) + (lo - 0xDC00));
            i++;
        } else {
            cps.push_back(u);
        }
    }
    printf("code points: %d\n", (int)cps.size());
    show("reversed by code point: ", cps);             // correct
    show("reversed by code unit (broken): ", units);   // splits the surrogate pair
    return 0;
}
// Time O(N), space O(N).

