using System;
using System.Collections.Generic;

class Program {
    static string Hex(int cp) {
        return "U+" + cp.ToString("X");
    }

    static void Main() {
        // 'a', one emoji (code point U+1F600, stored as two chars), then 'b'.
        string s = "a\U0001F600b";
        Console.WriteLine("text: a, emoji U+1F600, b");
        Console.WriteLine("UTF-16 code units (length): " + s.Length);

        // Join each surrogate pair into one code point.
        List<int> cps = new List<int>();
        for (int i = 0; i < s.Length; i++) {
            cps.Add(char.ConvertToUtf32(s, i));
            if (char.IsHighSurrogate(s[i])) i++;      // skip the second half of the pair
        }
        Console.WriteLine("code points: " + cps.Count);

        // Correct reverse: walk the code points backwards.
        List<string> good = new List<string>();
        for (int i = cps.Count - 1; i >= 0; i--) good.Add(Hex(cps[i]));
        Console.WriteLine("reversed by code point: " + string.Join(" ", good));

        // Wrong reverse: walking chars backwards splits the surrogate pair.
        List<string> bad = new List<string>();
        for (int i = s.Length - 1; i >= 0; i--) bad.Add(Hex(s[i]));
        Console.WriteLine("reversed by code unit (broken): " + string.Join(" ", bad));
    }
    // Time O(N), space O(N).
}

