public class Main {
    // Full table: (n+1) x (m+1) cells.
    static int lcsFull(String a, String b) {
        int n = a.length(), m = b.length();
        int[][] dp = new int[n + 1][m + 1];
        for (int i = 1; i <= n; i++)
            for (int j = 1; j <= m; j++)
                dp[i][j] = a.charAt(i - 1) == b.charAt(j - 1) ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
        return dp[n][m];
    }

    // Row i only reads row i-1, so two rows of m+1 cells are enough.
    static int lcsRolling(String a, String b) {
        int n = a.length(), m = b.length();
        int[] prev = new int[m + 1], cur = new int[m + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++)
                cur[j] = a.charAt(i - 1) == b.charAt(j - 1) ? prev[j - 1] + 1 : Math.max(prev[j], cur[j - 1]);
            int[] t = prev; prev = cur; cur = t;   // swap the rows, no copying
        }
        return prev[m];
    }

    public static void main(String[] args) {
        String a = "AGGTAB", b = "GXTXAYB";
        System.out.println("a = " + a + ", b = " + b);
        System.out.println("full table: LCS = " + lcsFull(a, b) + ", cells = " + (a.length() + 1) * (b.length() + 1));
        System.out.println("two rows:   LCS = " + lcsRolling(a, b) + ", cells = " + 2 * (b.length() + 1));
    }
    // Both O(N*M) time. Space: O(N*M) for the full table, O(M) for two rows.
}

